with base as (select *, coalesce(humidity, 0) as humidity_filled, date_trunc('year', reading_ts) as reading_ts_period from device_readings where reading_ts > timestamp '2025-09-01 01:00:00'), gaps as (select *, case when reading_ts - lag(reading_ts) over (partition by device_code order by reading_ts, id) > interval 45 minutes then 1 else 0 end as session_start_flag from base), sessions_device_readings as (select id, device_code, reading_ts, temp_c, humidity, firmware, sum(session_start_flag) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as island_id from gaps) select case when temp_c >= 41.5 then 'LARGE' else 'SMALL' end as temp_c_tier, date_trunc('day', reading_ts) as activity_day, max(temp_c) filter (where device_code = 'DV-01') as dv_01_max_temp_c, min(reading_ts) as first_seen, sum(case when device_code = 'DV-02' then island_id else 0 end) as dv_02_island_id, rank() over (partition by case when temp_c >= 41.5 then 'LARGE' else 'SMALL' end order by max(temp_c) filter (where device_code = 'DV-01') desc) as dv_01_max_temp_c_rank from sessions_device_readings group by case when temp_c >= 41.5 then 'LARGE' else 'SMALL' end, date_trunc('day', reading_ts)
